        // same content already streamed delta-by-delta on /v1/agent/events.
        record_prompt_result(
            &bg_state,
            request_id,
            &res,
            Some(ocean_core::EVENT_ORIGIN_AGENT),
        )
        .await;

        tracing::info!(
            turn_id = %turn_id,
            request_id = %request_id,
            session_id = %session_id,
            ok = res.ok,
            wall_ms = res.wall_ms,
            input_tokens = res.usage.input,
            output_tokens,
