   592	    fn issue_lease(&self, session_id: &str, min_seq: u64) -> (String, i64) {
   593	        let now = Instant::now();
   594	        let mut leases = self
   595	            .leases
   596	            .lock()
   597	            .unwrap_or_else(|poison| poison.into_inner());
   598	        leases.retain(|_, lease| lease.expires > now);
   599	        if leases.len() >= MAX_LEASES {
   600	            if let Some(oldest) = leases
   601	                .iter()
   602	                .min_by_key(|(_, lease)| lease.expires)
   603	                .map(|(id, _)| id.clone())
   604	            {
   605	                leases.remove(&oldest);
   606	            }
   607	        }
   608	        let id = Uuid::new_v4().to_string();
   609	        let expires_ms = now_ms().saturating_add(self.lease_duration.as_millis() as i64);
   610	        leases.insert(
   611	            id.clone(),
   612	            Lease {
   613	                session_id: session_id.to_string(),
   614	                min_seq,
   615	                expires: now + self.lease_duration,
   616	            },
   617	        );
   618	        (id, expires_ms)
   619	    }
