   331	    /// Atomically subscribe to the live broadcast and snapshot the replay
   332	    /// buffer under the same lock, so no event can slip between the two. If
   333	    /// `last_event_id` is present and still in the buffer, returns the buffered
   334	    /// envelopes strictly AFTER it (in emission order) for replay; otherwise the
   335	    /// replay vector is empty (the id aged out, or no header was sent), and the
   336	    /// caller just attaches the live stream — matching pre-OCEAN-129 behavior.
   337	    ///
   338	    /// Holding the `history` lock across `self.tx.subscribe()` is the seam
   339	    /// guarantee: `emit` takes the same lock before it sends, so every event is
   340	    /// either already in the snapshot (and will be replayed) or will arrive on
   341	    /// the freshly-created live receiver — never both, never neither. Replayed
   342	    /// ids are still deduped against the live tail by the handler as a belt-and-
   343	    /// suspenders measure.
   344	    pub(crate) fn subscribe_with_replay(
   345	        &self,
   346	        last_event_id: Option<Uuid>,
   347	    ) -> (
   348	        Vec<AgentEventEnvelope>,
   349	        broadcast::Receiver<AgentEventEnvelope>,
   350	    ) {
   351	        let history = self.lock_history();
   352	        let rx = self.tx.subscribe();
   353	        let replay = match last_event_id {
   354	            Some(want) => match history.iter().position(|env| env.id == want) {
   355	                // Found: replay everything strictly after it.
   356	                Some(pos) => history.iter().skip(pos + 1).cloned().collect(),
   357	                // Not found (aged out / unknown id): no replay.
   358	                None => Vec::new(),
   359	            },
   360	            None => Vec::new(),
   361	        };
   362	        (replay, rx)
   363	    }
