 511	    /// Validate and acknowledge only the cursor supplied by a new HTTP request.
 512	    /// Internal SQLite pages must never call this: bytes queued to an SSE channel
 513	    /// are not proof that the client received them.
 514	    pub(crate) fn begin_tail_request(
 515	        &self,
 516	        session_id: &str,
 517	        raw_cursor: &str,
 518	        lease_id: &str,
 519	    ) -> std::result::Result<(), ProjectionReset> {
 520	        let cursor = self.validate_cursor_identity(session_id, raw_cursor)?;
 521	        self.validate_lease(session_id, lease_id, cursor.seq)?;
 522	        self.validate_cursor_position(session_id, cursor.seq)?;
 523	        self.acknowledge_lease(lease_id, cursor.seq)
 524	    }
 525	
 526	    pub(crate) fn page_after(
 527	        &self,
 528	        session_id: &str,
 529	        raw_cursor: &str,
 530	        lease_id: &str,
 531	    ) -> std::result::Result<Vec<SessionProjectionFrame>, ProjectionReset> {
 532	        let cursor = self.validate_cursor_identity(session_id, raw_cursor)?;
 533	        self.validate_lease(session_id, lease_id, cursor.seq)?;
 534	        let db = self.db.lock().unwrap_or_else(|poison| poison.into_inner());
 535	        let Some(row) =
 536	            load_row(&db, &self.epoch, session_id).map_err(|_| ProjectionReset::Faulted)?
 537	        else {
 538	            if cursor.seq == 0 {
 539	                return Ok(Vec::new());
 540	            }
 541	            return Err(ProjectionReset::Future);
 542	        };
 543	        if cursor.seq > row.latest {
 544	            return Err(ProjectionReset::Future);
 545	        }
 546	        let earliest: Option<u64> = db
 547	            .query_row(
 548	                "SELECT MIN(seq) FROM session_projection_events WHERE epoch=?1 AND session_id=?2",
 549	                params![&*self.epoch, session_id],
 550	                |row| row.get(0),
 551	            )
 552	            .optional()
 553	            .map_err(|_| ProjectionReset::Faulted)?
 554	            .flatten();
 555	        if cursor.seq < row.latest
 556	            && earliest.is_none_or(|first| cursor.seq.saturating_add(1) < first)
 557	        {
 558	            return Err(ProjectionReset::Retention);
 559	        }
 560	        let through = cursor.seq.saturating_add(PAGE_LIMIT as u64);
 561	        let frames = query_frames(
 562	            &db,
 563	            &self.epoch,
 564	            session_id,
 565	            cursor.seq,
 566	            through.min(row.latest),
 567	        )
 568	        .map_err(|_| ProjectionReset::Faulted)?;
 569	        drop(db);
 570	        // Fetching or queueing a page is not an acknowledgement. Only renew the
 571	        // expiry; min_seq remains the cursor from begin_tail_request.
 572	        self.renew_lease_expiry(lease_id)?;
 573	        Ok(frames)
 574	    }
