 621	    fn validate_cursor_identity(
 622	        &self,
 623	        session_id: &str,
 624	        raw_cursor: &str,
 625	    ) -> std::result::Result<ProjectionCursor, ProjectionReset> {
 626	        if self.is_faulted(session_id) {
 627	            return Err(ProjectionReset::Faulted);
 628	        }
 629	        let cursor = ProjectionCursor::parse(raw_cursor)?;
 630	        if cursor.epoch.as_str() != self.epoch.as_ref() {
 631	            return Err(ProjectionReset::WrongEpoch);
 632	        }
 633	        if cursor.session_hash != session_hash(session_id) {
 634	            return Err(ProjectionReset::WrongSession);
 635	        }
 636	        Ok(cursor)
 637	    }
