 639	    fn validate_cursor_position(
 640	        &self,
 641	        session_id: &str,
 642	        seq: u64,
 643	    ) -> std::result::Result<(), ProjectionReset> {
 644	        let db = self.db.lock().unwrap_or_else(|poison| poison.into_inner());
 645	        let Some(row) =
 646	            load_row(&db, &self.epoch, session_id).map_err(|_| ProjectionReset::Faulted)?
 647	        else {
 648	            return if seq == 0 {
 649	                Ok(())
 650	            } else {
 651	                Err(ProjectionReset::Future)
 652	            };
 653	        };
 654	        if seq > row.latest {
 655	            return Err(ProjectionReset::Future);
 656	        }
 657	        let earliest: Option<u64> = db
 658	            .query_row(
 659	                "SELECT MIN(seq) FROM session_projection_events WHERE epoch=?1 AND session_id=?2",
 660	                params![&*self.epoch, session_id],
 661	                |row| row.get(0),
 662	            )
 663	            .optional()
 664	            .map_err(|_| ProjectionReset::Faulted)?
 665	            .flatten();
 666	        if seq < row.latest && earliest.is_none_or(|first| seq.saturating_add(1) < first) {
 667	            return Err(ProjectionReset::Retention);
 668	        }
 669	        Ok(())
 670	    }
