 672	    fn validate_lease(
 673	        &self,
 674	        session_id: &str,
 675	        lease_id: &str,
 676	        cursor_seq: u64,
 677	    ) -> std::result::Result<(), ProjectionReset> {
 678	        let now = Instant::now();
 679	        let mut leases = self
 680	            .leases
 681	            .lock()
 682	            .unwrap_or_else(|poison| poison.into_inner());
 683	        let Some(lease) = leases.get(lease_id).cloned() else {
 684	            return Err(ProjectionReset::InvalidLease);
 685	        };
 686	        if lease.expires <= now {
 687	            leases.remove(lease_id);
 688	            return Err(ProjectionReset::ExpiredLease);
 689	        }
 690	        if lease.session_id != session_id {
 691	            return Err(ProjectionReset::LeaseSessionMismatch);
 692	        }
 693	        if cursor_seq < lease.min_seq {
 694	            return Err(ProjectionReset::InvalidLease);
 695	        }
 696	        Ok(())
 697	    }
