 699	    fn acknowledge_lease(
 700	        &self,
 701	        lease_id: &str,
 702	        acknowledged_seq: u64,
 703	    ) -> std::result::Result<(), ProjectionReset> {
 704	        let now = Instant::now();
 705	        let mut leases = self
 706	            .leases
 707	            .lock()
 708	            .unwrap_or_else(|poison| poison.into_inner());
 709	        let Some(lease) = leases.get_mut(lease_id) else {
 710	            return Err(ProjectionReset::InvalidLease);
 711	        };
 712	        if lease.expires <= now {
 713	            leases.remove(lease_id);
 714	            return Err(ProjectionReset::ExpiredLease);
 715	        }
 716	        if acknowledged_seq < lease.min_seq {
 717	            return Err(ProjectionReset::InvalidLease);
 718	        }
 719	        lease.min_seq = acknowledged_seq;
 720	        lease.expires = now + self.lease_duration;
 721	        Ok(())
 722	    }
