 724	    fn renew_lease_expiry(&self, lease_id: &str) -> std::result::Result<(), ProjectionReset> {
 725	        let now = Instant::now();
 726	        let mut leases = self
 727	            .leases
 728	            .lock()
 729	            .unwrap_or_else(|poison| poison.into_inner());
 730	        let Some(lease) = leases.get_mut(lease_id) else {
 731	            return Err(ProjectionReset::InvalidLease);
 732	        };
 733	        if lease.expires <= now {
 734	            leases.remove(lease_id);
 735	            return Err(ProjectionReset::ExpiredLease);
 736	        }
 737	        lease.expires = now + self.lease_duration;
 738	        Ok(())
 739	    }
