 741	    fn compact(&self, pressure_only: bool) -> Result<()> {
 742	        let now = Instant::now();
 743	        let protected_by_session = {
 744	            let mut leases = self
 745	                .leases
 746	                .lock()
 747	                .unwrap_or_else(|poison| poison.into_inner());
 748	            leases.retain(|_, lease| lease.expires > now);
 749	            let mut protected: HashMap<String, u64> = HashMap::new();
 750	            for lease in leases.values() {
 751	                protected
 752	                    .entry(lease.session_id.clone())
 753	                    .and_modify(|seq| *seq = (*seq).min(lease.min_seq))
 754	                    .or_insert(lease.min_seq);
 755	            }
 756	            protected
 757	        };
 758	        let cutoff_ms = now_ms().saturating_sub(self.lease_duration.as_millis() as i64);
 759	        let pressure = self.logical_bytes.load(Ordering::Relaxed) > self.budget_bytes;
 760	        if pressure_only && !pressure {
5180	        StatusCode::OK,
5181	        Json(json!({
5182	            "ok": true,
5183	            "topic_id": topic_id,
5184	            "mark_id": mark_id,
5185	        })),
5186	    )
5187	}
