5218	    State(state): State<AppState>,
5219	    Path(session_id): Path<SessionId>,
5220	) -> (StatusCode, Json<SessionResponse>) {
5221	    match state.runtime.session_detail(session_id) {
5222	        Ok(mut session) => {
5223	            // A persistence rename and its internal checkpoint cross an async
5224	            // bridge. Bound the alignment wait; never return a cursor for a
5225	            // different file revision. Legacy clients still receive the normal
5226	            // session body if the projection is momentarily unavailable.
5227	            let mut projection = None;
5228	            if let Some(store) = state.agent_events.projection() {
5229	                for attempt in 0..=20 {
5230	                    match store.snapshot(
5231	                        &session_id.to_string(),
5232	                        session.persistence_revision,
5233	                        normalized_projection_checkpoint(&session),
5234	                    ) {
5235	                        Ok(snapshot) => {
5236	                            projection = Some(snapshot);
5237	                            break;
5238	                        }
5239	                        Err(session_projection::ProjectionReset::RevisionMismatch)
5240	                            if attempt < 20 =>
5241	                        {
5242	                            tokio::time::sleep(std::time::Duration::from_millis(5)).await;
5243	                            match state.runtime.session_detail(session_id) {
5244	                                Ok(refreshed) => session = refreshed,
5245	                                Err(_) => break,
5246	                            }
5247	                        }
5248	                        Err(reset) => {
5249	                            tracing::warn!(%session_id, reason = reset.reason(), "session projection snapshot unavailable");
5250	                            break;
5251	                        }
5252	                    }
5253	                }
5254	            }
5255	            enrich_session_detail(&state, &mut session).await;
5256	            (
5257	                StatusCode::OK,
5258	                Json(SessionResponse {
5259	                    ok: true,
5260	                    session: Some(session),
5261	                    projection,
5262	                    error: None,
5263	                }),
5264	            )
5265	        }
5266	        Err(error) if is_not_found(&error) => (
5267	            StatusCode::NOT_FOUND,
5268	            Json(SessionResponse {
5269	                ok: false,
5270	                session: None,
5271	                projection: None,
5272	                error: Some("session not found".into()),
5273	            }),
5274	        ),
5275	        Err(error) => {
5276	            tracing::warn!(%session_id, error = %error, "failed to read session detail");
5277	            (
5278	                StatusCode::INTERNAL_SERVER_ERROR,
5279	                Json(SessionResponse {
5280	                    ok: false,
5281	                    session: None,
5282	                    projection: None,
5283	                    error: Some("session could not be read".into()),
5284	                }),
5285	            )
