6929	/// Durable session-projection SSE tail. SQLite is authoritative; the broadcast
6930	/// receiver is only a wake hint. Subscribe-before-page plus paging on lag closes
6931	/// the snapshot/live seam without depending on the legacy UUID replay ring.
6932	async fn session_projection_events(
6933	    State(state): State<AppState>,
6934	    Query(query): Query<SessionProjectionEventsQuery>,
6935	    headers: HeaderMap,
6936	) -> Sse<impl Stream<Item = Result<Event, Infallible>>> {
6937	    let (tx, rx) = mpsc::channel(64);
6938	    let shutdown = state.shutdown.clone();
6939	    let stream_shutdown = state.shutdown.clone();
6940	    let session_id = query.session_id.to_string();
6941	    let cursor_result = projection_request_cursor(&headers, &query.after_cursor);
6942	    let lease_id = query.lease_id;
6943	    let projection = state.agent_events.projection();
6944	
6945	    tokio::spawn(async move {
6946	        let Some(store) = projection else {
6947	            let data = json!({ "type": "projection_reset", "reason": "projection_unavailable" })
6948	                .to_string();
6949	            let _ = send_projection_sse(
6950	                &tx,
6951	                &shutdown,
6952	                Event::default().event("projection_reset").data(data),
6953	            )
6954	            .await;
6955	            return;
6956	        };
6957	
6958	        // Register before validating/acknowledging the HTTP request cursor. Any
6959	        // append racing the first page is either visible in SQLite or leaves a
6960	        // buffered wake. Internal pages renew expiry but never acknowledge their
6961	        // queued tail; only this new request (query or Last-Event-ID) advances the
6962	        // lease minimum.
6963	        let mut wakes = store.subscribe();
6964	        let mut cursor = match cursor_result {
6965	            Ok(cursor) => cursor,
6966	            Err(reset) => {
6967	                let data =
6968	                    json!({ "type": "projection_reset", "reason": reset.reason() }).to_string();
6969	                let _ = send_projection_sse(
6970	                    &tx,
6971	                    &shutdown,
6972	                    Event::default().event("projection_reset").data(data),
6973	                )
6974	                .await;
6975	                return;
6976	            }
6977	        };
6978	        if let Err(reset) = store.begin_tail_request(&session_id, &cursor, &lease_id) {
6979	            let data = json!({ "type": "projection_reset", "reason": reset.reason() }).to_string();
6980	            let _ = send_projection_sse(
6981	                &tx,
6982	                &shutdown,
6983	                Event::default().event("projection_reset").data(data),
6984	            )
6985	            .await;
6986	            return;
6987	        }
6988	        let connection_deadline = tokio::time::Instant::now() + store.connection_lifetime();
6989	        loop {
6990	            if tokio::time::Instant::now() >= connection_deadline {
6991	                return;
6992	            }
6993	            match store.page_after(&session_id, &cursor, &lease_id) {
6994	                Ok(frames) if !frames.is_empty() => {
6995	                    for frame in frames {
6996	                        cursor = frame.cursor.clone();
6997	                        let data = serde_json::to_string(&frame).unwrap_or_else(|_| {
6998	                            json!({ "type": "projection_reset", "reason": "serialize_failed" })
6999	                                .to_string()
7000	                        });
7001	                        if !send_projection_sse_until(
7002	                            &tx,
7003	                            &shutdown,
7004	                            connection_deadline,
7005	                            Event::default()
7006	                                .id(frame.cursor)
7007	                                .event("session_projection")
7008	                                .data(data),
7009	                        )
7010	                        .await
7011	                        {
7012	                            return;
7013	                        }
7014	                    }
7015	                    continue;
7016	                }
7017	                Ok(_) => {}
7018	                Err(reset) => {
7019	                    let data = json!({
7020	                        "type": "projection_reset",
7021	                        "reason": reset.reason(),
7022	                    })
7023	                    .to_string();
7024	                    let _ = send_projection_sse_until(
7025	                        &tx,
7026	                        &shutdown,
7027	                        connection_deadline,
7028	                        Event::default().event("projection_reset").data(data),
7029	                    )
7030	                    .await;
7031	                    return;
7032	                }
7033	            }
7034	
7035	            tokio::select! {
7036	                _ = shutdown.cancelled() => return,
7037	                _ = tx.closed() => return,
7038	                _ = tokio::time::sleep_until(connection_deadline) => return,
7039	                wake = wakes.recv() => match wake {
7040	                    Ok(woken_session) if woken_session == session_id => {},
7041	                    Ok(_) => continue,
7042	                    Err(tokio::sync::broadcast::error::RecvError::Lagged(_)) => {},
7043	                    Err(tokio::sync::broadcast::error::RecvError::Closed) => return,
7044	                }
7045	            }
7046	        }
7047	    });
7048	
7049	    let stream = sse_until_shutdown(ReceiverStream::new(rx), stream_shutdown);
7050	    Sse::new(stream).keep_alive(KeepAlive::new().interval(SSE_KEEPALIVE_INTERVAL))
7051	}
