 281	    pub(crate) fn emit(&self, event: AgentTurnEvent) {
 282	        if let Some(projection) = &self.projection {
 283	            if let Err(error) = projection.append_agent(&event) {
 284	                if let Some(session_id) = event.session_id() {
 285	                    projection.fault(&session_id.to_string(), &error);
 286	                } else {
 287	                    tracing::error!(%error, "unscoped projection agent append failed");
 288	                }
 289	            }
 290	        }
 291	        // This is an estimate of retained replay bytes and the exact JSON body
 292	        // shape SSE will later serialize (excluding the envelope UUID/SSE
 293	        // framing). A serialization failure is conservatively treated as
 294	        // oversized: the event stays live but is not retained for replay.
 295	        let encoded_bytes = serialized_event_bytes(&event);
 296	        let envelope = AgentEventEnvelope {
 297	            id: Uuid::new_v4(),
 298	            event,
 299	            encoded_bytes,
 300	        };
 301	
 302	        // Record into the bounded replay ring BEFORE broadcasting so that a
 303	        // client which subscribes (and snapshots the buffer) concurrently with
 304	        // this emit can never observe the live event without also finding it in
 305	        // the replay buffer — closing the gap/dupe seam (OCEAN-129). Count and
 306	        // serialized-byte limits are enforced together under the history lock.
 307	        {
 308	            let mut history = self.lock_history();
 309	            history.encoded_bytes = history.encoded_bytes.saturating_add(envelope.encoded_bytes);
 310	            history.envelopes.push_back(envelope.clone());
 311	            while history.envelopes.len() > self.history_limit
 312	                || history.encoded_bytes > self.history_byte_limit
 313	            {
 314	                let Some(evicted) = history.envelopes.pop_front() else {
 315	                    break;
 316	                };
 317	                history.encoded_bytes = history.encoded_bytes.saturating_sub(evicted.encoded_bytes);
 318	            }
 319	        }
 320	
 321	        // `broadcast::send` errors only when there are no live receivers (no SSE
 322	        // client subscribed to `/v1/agent/events`). That's expected during idle
 323	        // periods, so debug — not warn. Per-subscriber *lag* (a slow client that
 324	        // overflows the ring buffer) surfaces on the RECEIVE side as
 325	        // `Lagged(n)`, which the SSE handlers log at warn (OCEAN-87).
 326	        if self.tx.send(envelope).is_err() {
 327	            tracing::debug!("AgentEventBus: no active subscribers for event");
 328	        }
 329	    }
 330	
 331	    /// Atomically subscribe to the live broadcast and snapshot the replay
 332	    /// buffer under the same lock, so no event can slip between the two. If
 333	    /// `last_event_id` is present and still in the buffer, returns the buffered
 334	    /// envelopes strictly AFTER it (in emission order) for replay; otherwise the
 335	    /// replay vector is empty (the id aged out, or no header was sent), and the
 336	    /// caller just attaches the live stream — matching pre-OCEAN-129 behavior.
 337	    ///
 338	    /// Holding the `history` lock across `self.tx.subscribe()` is the seam
 339	    /// guarantee: `emit` takes the same lock before it sends, so every event is
 340	    /// either already in the snapshot (and will be replayed) or will arrive on
 341	    /// the freshly-created live receiver — never both, never neither. Replayed
 342	    /// ids are still deduped against the live tail by the handler as a belt-and-
 343	    /// suspenders measure.
 344	    pub(crate) fn subscribe_with_replay(
 345	        &self,
 346	        last_event_id: Option<Uuid>,
 347	    ) -> (
 348	        Vec<AgentEventEnvelope>,
 349	        broadcast::Receiver<AgentEventEnvelope>,
 350	    ) {
 351	        let history = self.lock_history();
 352	        let rx = self.tx.subscribe();
 353	        let replay = match last_event_id {
 354	            Some(want) => match history.iter().position(|env| env.id == want) {
 355	                // Found: replay everything strictly after it.
 356	                Some(pos) => history.iter().skip(pos + 1).cloned().collect(),
 357	                // Not found (aged out / unknown id): no replay.
 358	                None => Vec::new(),
 359	            },
 360	            None => Vec::new(),
 361	        };
 362	        (replay, rx)
 363	    }
