 366	        &self,
 367	        session_id: &str,
 368	        revision: u64,
 369	        snapshot: serde_json::Value,
 370	    ) {
 371	        if let Some(projection) = &self.projection {
 372	            if let Err(error) = projection.checkpoint(session_id, revision, snapshot) {
 373	                projection.fault(session_id, &error);
 374	            }
 375	        }
 376	    }
