 382	    /// OCEAN-305: atomically subscribe to the live broadcast and snapshot the
 383	    /// ENTIRE replay buffer (in emission order) for replay — for a client that
 384	    /// has no `Last-Event-ID` anchor at all because it was previously connected
 385	    /// unscoped (and thus deliberately received nothing session-bearing it
 386	    /// could anchor on). The caller is expected to apply the same per-event
 387	    /// session scoping it applies to the live stream, so a session-scoped
 388	    /// subscriber only ever sees its own session's buffered events.
 389	    ///
 390	    /// Holding the `history` lock across `self.tx.subscribe()` preserves the
 391	    /// same seam guarantee as [`subscribe_with_replay`]: every event is either
 392	    /// in the snapshot (replayed) or arrives on the fresh live receiver —
 393	    /// never both, never neither.
 394	    pub(crate) fn subscribe_with_full_replay(
 395	        &self,
 396	    ) -> (
 397	        Vec<AgentEventEnvelope>,
 398	        broadcast::Receiver<AgentEventEnvelope>,
 399	    ) {
 400	        let history = self.lock_history();
 401	        let rx = self.tx.subscribe();
 402	        let replay = history.iter().cloned().collect();
 403	        (replay, rx)
 404	    }
 405	}
