 491	///    tail refetch checkpoint restarts this algorithm.
 492	#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
 493	pub struct SessionProjection {
 494	    pub version: u32,
 495	    pub cursor: String,
 496	    pub checkpoint_revision: u64,
 497	    /// Latest visible durable replacement. Live clients receive the same typed
 498	    /// payload on the checkpoint source.
