 500	    pub checkpoint: Option<SessionProjectionCheckpoint>,
 501	    /// Identified bounded replay lease required by the projection tail.
 502	    pub lease_id: String,
 503	    pub lease_expires_ms: i64,
 504	    #[serde(default)]
 505	    pub pending_events: Vec<SessionProjectionFrame>,
 506	    #[serde(default)]
